654	fn merkle_root_of_file(path: &Path) -> Result<[u8; 32], String> {
655	    let data = fs::read(path).map_err(|e| format!("cannot read '{}': {e}", display_path(path)))?;
656	    Ok(mth(&split_records(&data)))
