1	//! End-to-end regression tests for `roottrace verify` on trees whose size
2	//! sits at the unsigned 64-bit boundary: 2^63 (9223372036854775808, a
3	//! power-of-two tree), 2^63+1 (9223372036854775809, uneven) and 2^64-1
4	//! (18446744073709551615, uneven). Such batches can never be materialised,
5	//! so the proofs are synthetic: one fixed target record and an audit path
6	//! whose element i is the 64-character lowercase hex of i. The trusted roots
7	//! are fixed constants generated by `tests/reference/rfc6962_vectors.py`,
8	//! which recombines (record, leaf_index, tree_size, audit_path) with two
9	//! structurally different, hashlib-based RFC 6962 verifiers that must agree;
10	//! they are never derived from roottrace output.
11	//!
12	//! Coverage:
13	//!   * valid proofs verify at the first/last record and on both sides of the
14	//!     left/right subtree boundary, including leaf indices past the 32-bit
15	//!     range: stdout is exactly "verified\n", exit 0, stderr empty
16	//!   * tree sizes and indices keep their exact 64-bit integer meaning: the
17	//!     high bit set is neither truncated, negated nor treated as a smaller
18	//!     batch (off-by-one trusted sizes and off-by-one leaf indices fail)
19	//!   * uneven trees keep the RFC geometry: the last record of a 2^63+1 tree
20	//!     has a one-hash path (no duplicated tail record, no padding)
21	//!   * a path with one hash missing, one hash extra, or one hash altered
22	//!     fails verification (exit 1, empty stdout, "verification failed" on
23	//!     stderr) — never a usage error or an abnormal termination
24	//!   * the trusted tree size comes only from the command line: with record
25	//!     and path unchanged, any other legal trusted size fails even though
26	//!     the proof carries its own self-consistent tree_size
27	//!   * for the maximum tree size, leaf_index == tree_size is an INVALID
28	//!     PROOF (exit 1, "invalid proof"), kept distinct from a cryptographic
29	//!     verification failure
30	
31	mod common;
32	
33	use std::process::Command;
34	
35	use common::TempFile;
36	
37	/// The fixed target record of every big-tree case (NUL and non-UTF-8 bytes
38	/// included, so record-byte fidelity stays exercised).
39	const BIG_TREE_RECORD: &[u8] = b"big-tree-record\x00\xff\xfe";
40	
41	struct BigCase {
42	    size: u64,
43	    index: u64,
44	    depth: usize,
45	    root: &'static str,
46	}
47	
48	// Generated by tests/reference/rfc6962_vectors.py (two independent root
49	// computations agree on every case).
50	const BIG_TREE_CASES: &[BigCase] = &[
51	    // 2**63 (power-of-two tree), first record; audit_path depth 63
52	    BigCase { size: 9223372036854775808, index: 0, depth: 63, root: "ee3d1ca8d1cb646feeaa90be0fb22c6d8674b545ab84e113a3fe41af630838dc" },
53	    // 2**63, record 2**32-1 (top of 32-bit range); audit_path depth 63
54	    BigCase { size: 9223372036854775808, index: 4294967295, depth: 63, root: "92898a452dc9806a49b20c0f1387e3f595275a532f9384e6982ea1d5c1433770" },
55	    // 2**63, record 2**32 (first index past 32 bits); audit_path depth 63
56	    BigCase { size: 9223372036854775808, index: 4294967296, depth: 63, root: "afcfe7edcae41e08965824b245fd42bd162c459feecedd1bf581349b664d8ebe" },
57	    // 2**63, record k-1 (last of left subtree); audit_path depth 63
58	    BigCase { size: 9223372036854775808, index: 4611686018427387903, depth: 63, root: "b17f9560c7184c222ad3f7f0cb7634285c0eebf1e197a50953714c4af1a32404" },
59	    // 2**63, record k (first of right subtree); audit_path depth 63
60	    BigCase { size: 9223372036854775808, index: 4611686018427387904, depth: 63, root: "a386e67cd2e721b651aadb134199e3f32ac3f3181e27b2305917ae8a1bf296a2" },
61	    // 2**63, last record; audit_path depth 63
62	    BigCase { size: 9223372036854775808, index: 9223372036854775807, depth: 63, root: "c035bef423e3cc7dcaa0a23687221787e739ef1ad6717b6c9e562addde480fc6" },
63	    // 2**63+1 (uneven), first record; audit_path depth 64
64	    BigCase { size: 9223372036854775809, index: 0, depth: 64, root: "00374def40979015a9865a6e90b2fbd6effc8e235befab92877dcdf5e63f0361" },
65	    // 2**63+1 (uneven), record k-1 (last of left subtree); audit_path depth 64
66	    BigCase { size: 9223372036854775809, index: 9223372036854775807, depth: 64, root: "b44d5ad09c3f5dbfb1e67033863f8a6253d79f5b12ec2f3a591c6289d4da40e1" },
67	    // 2**63+1 (uneven), last record = k (lone right subtree); audit_path depth 1
68	    BigCase { size: 9223372036854775809, index: 9223372036854775808, depth: 1, root: "e3004442ff263eaa1f454e07a87f17253cb9aadc06d4e2df78e23db1b3f82fd3" },
69	    // 2**64-1 (uneven), first record; audit_path depth 64
