71	    // 2**64-1 (uneven), record k-1 (last of left subtree); audit_path depth 64
72	    BigCase { size: 18446744073709551615, index: 9223372036854775807, depth: 64, root: "b44d5ad09c3f5dbfb1e67033863f8a6253d79f5b12ec2f3a591c6289d4da40e1" },
73	    // 2**64-1 (uneven), record k (first of right subtree); audit_path depth 64
74	    BigCase { size: 18446744073709551615, index: 9223372036854775808, depth: 64, root: "0173223adb9663b2cf479e79b5a9e8533ca58a72128e06b3e784a4b34df5f0bb" },
75	    // 2**64-1 (uneven), last record; audit_path depth 63
76	    BigCase { size: 18446744073709551615, index: 18446744073709551614, depth: 63, root: "c035bef423e3cc7dcaa0a23687221787e739ef1ad6717b6c9e562addde480fc6" },
77	];
78	
79	const SIZE_POW63: u64 = 9223372036854775808;
80	const SIZE_POW63_PLUS1: u64 = 9223372036854775809;
81	const SIZE_MAX: u64 = 18446744073709551615;
82	
83	/// The synthetic audit path shared with the reference generator: element i
84	/// is the 64-character lowercase hex of i.
85	fn audit_path(depth: usize) -> Vec<String> {
86	    (0..depth).map(|i| format!("{i:064x}")).collect()
87	}
88	
89	fn proof_json(size: u64, index: u64, root: &str, path: &[String]) -> String {
90	    let mut out =
91	        format!("{{\"tree_size\":{size},\"leaf_index\":{index},\"root\":\"{root}\",\"audit_path\":[");
92	    for (i, h) in path.iter().enumerate() {
93	        if i > 0 {
94	            out.push(',');
95	        }
96	        out.push('"');
97	        out.push_str(h);
98	        out.push('"');
99	    }
100	    out.push_str("]}");
101	    out
102	}
103	
104	fn run(record: &std::path::Path, proof: &std::path::Path, size: &str, root: &str) -> std::process::Output {
105	    Command::new(common::bin())
106	        .arg("verify")
107	        .arg(record)
108	        .arg(proof)
109	        .arg(size)
110	        .arg(root)
111	        .output()
112	        .expect("failed to execute roottrace binary")
113	}
114	
115	/// The documented success path, checked strictly: exit status 0, stdout
116	/// exactly "verified\n", stderr empty.
117	fn assert_verified(desc: &str, record: &[u8], proof: &[u8], size: &str, root: &str) {
118	    let rec = TempFile::create(record);
119	    let prf = TempFile::create(proof);
120	    let out = run(&rec.path, &prf.path, size, root);
121	    if out.status.code() != Some(0) || out.stdout != b"verified\n" || !out.stderr.is_empty() {
122	        panic!(
123	            "[{desc}] expected verified/exit0/empty-stderr\n\
124	             status: {:?}\nstdout: {:?}\nstderr: {}",
125	            out.status.code(),
126	            out.stdout,
127	            String::from_utf8_lossy(&out.stderr),
128	        );
129	    }
130	}
131	
132	/// A cryptographic mismatch: exit status 1 (not a usage error, not a
133	/// crash), stdout empty, stderr reporting the verification failure.
134	fn assert_verification_failed(desc: &str, record: &[u8], proof: &[u8], size: &str, root: &str) {
135	    let rec = TempFile::create(record);
136	    let prf = TempFile::create(proof);
137	    let out = run(&rec.path, &prf.path, size, root);
138	    assert_eq!(out.status.code(), Some(1), "[{desc}] must exit 1");
139	    assert!(out.stdout.is_empty(), "[{desc}] stdout must be empty, got {:?}", out.stdout);
140	    let err = String::from_utf8_lossy(&out.stderr);
141	    assert!(err.contains("verification failed"), "[{desc}] stderr: {err}");
142	}
