144	/// A malformed proof: exit status 1, stdout empty, stderr reporting the
145	/// format problem — and NOT phrased as a cryptographic verification
146	/// failure, so the two stay distinguishable.
147	fn assert_invalid_proof(desc: &str, record: &[u8], proof: &[u8], size: &str, root: &str) {
148	    let rec = TempFile::create(record);
149	    let prf = TempFile::create(proof);
150	    let out = run(&rec.path, &prf.path, size, root);
151	    assert_eq!(out.status.code(), Some(1), "[{desc}] malformed proof must exit 1");
152	    assert!(out.stdout.is_empty(), "[{desc}] malformed proof must not touch stdout");
153	    let err = String::from_utf8_lossy(&out.stderr);
154	    assert!(err.contains("invalid proof"), "[{desc}] stderr: {err}");
155	    assert!(
156	        !err.contains("verification failed"),
157	        "[{desc}] a format problem must not be reported as a verification failure: {err}"
158	    );
