165	// --- Success: first/last records and both sides of the subtree boundary ----
166	
167	#[test]
168	fn big_tree_proofs_verify_at_boundary_positions() {
169	    for case in BIG_TREE_CASES {
170	        let desc = format!(
171	            "tree_size={} leaf_index={} (depth {})",
172	            case.size, case.index, case.depth
173	        );
174	        let proof = case_proof(case);
175	        // The proof and the command line must carry the exact decimal
176	        // spelling of the full-width values (no float, no truncation).
177	        assert!(proof.contains(&format!("\"tree_size\":{}", case.size)), "{desc}");
178	        assert!(proof.contains(&format!("\"leaf_index\":{}", case.index)), "{desc}");
179	        assert_verified(&desc, BIG_TREE_RECORD, proof.as_bytes(), &case.size.to_string(), case.root);
180	    }
