206	
207	#[test]
208	fn big_tree_trusted_size_is_exact_and_never_taken_from_the_proof() {
209	    for case in BIG_TREE_CASES {
210	        let proof = case_proof(case);
211	        // Record, path and proof are unchanged; only the trusted size moves
212	        // to another legal value. The proof's own tree_size must not
213	        // substitute for the trusted one, however self-consistent it is.
214	        let mut variants = vec![case.size - 1, 9];
215	        if case.size < SIZE_MAX {
216	            variants.push(case.size + 1);
217	        }
218	        for other in variants {
219	            assert_verification_failed(
220	                &format!(
221	                    "trusted size {other} vs proof tree_size {} (leaf_index {})",
222	                    case.size, case.index
223	                ),
224	                BIG_TREE_RECORD,
