233	#[test]
234	fn big_tree_leaf_index_participates_exactly_beyond_32_bits() {
235	    // Same record, same path, same root, same tree size — only the claimed
236	    // position moves by one. The recombination geometry changes, so the
237	    // proof must fail; an index truncated to 32 bits (or to the signed
238	    // range) would conflate these positions.
239	    let case = BIG_TREE_CASES
240	        .iter()
241	        .find(|c| c.size == SIZE_POW63 && c.index == 4294967296)
242	        .expect("the 2^32 index case");
243	    for off_by_one in [case.index - 1, case.index + 1] {
244	        let proof = proof_json(case.size, off_by_one, case.root, &audit_path(case.depth));
245	        assert_verification_failed(
246	            &format!("leaf_index {off_by_one} reusing the proof for {}", case.index),
247	            BIG_TREE_RECORD,
248	            proof.as_bytes(),
249	            &case.size.to_string(),
250	            case.root,
251	        );
252	    }
253	    // The 2^32-1 / 2^32 pair must not be conflated either: the proof for
254	    // one must fail at the other.
255	    let below = BIG_TREE_CASES
256	        .iter()
257	        .find(|c| c.size == SIZE_POW63 && c.index == 4294967295)
258	        .expect("the 2^32-1 index case");
259	    let proof = proof_json(case.size, below.index, case.root, &audit_path(case.depth));
