289	#[test]
290	fn big_tree_path_missing_extra_or_altered_hash_fails() {
291	    for case in BIG_TREE_CASES {
292	        let path = audit_path(case.depth);
293	        let desc = format!("tree_size={} leaf_index={}", case.size, case.index);
