301	            &case.size.to_string(),
302	            case.root,
303	        );
304	
305	        // One hash too many.
306	        let mut long = path.clone();
307	        long.push(format!("{:064x}", case.depth));
308	        assert_verification_failed(
309	            &format!("{desc}: path one hash too long"),
310	            BIG_TREE_RECORD,
311	            proof_json(case.size, case.index, case.root, &long).as_bytes(),
312	            &case.size.to_string(),
313	            case.root,
314	        );
315	
316	        // One hash altered in content (same length, same count).
317	        let mut altered = path.clone();
318	        let mid = altered.len() / 2;
319	        let first = altered[mid].remove(0);
320	        let replacement = if first == '0' { '1' } else { '0' };
321	        altered[mid].insert(0, replacement);
322	        assert_verification_failed(
323	            &format!("{desc}: path hash {mid} altered"),
324	            BIG_TREE_RECORD,
325	            proof_json(case.size, case.index, case.root, &altered).as_bytes(),
326	            &case.size.to_string(),
327	            case.root,
328	        );
329	    }
330	}
