    /// Same check as [`super::verify_inclusion`], but the two proof-related
    /// failures carry the internal diagnostic text. This is for the bundled
    /// command line only, whose stderr historically printed a reason; library
    /// users match on [`super::VerifyInclusionError`].
    pub fn verify_inclusion_detailed(
        record: &[u8],
        proof: &[u8],
        trusted_tree_size: u64,
        trusted_root: &[u8; 32],
    ) -> Result<super::VerifiedInclusion, CliVerifyError> {
        if trusted_tree_size == 0 {
            return Err(CliVerifyError::InvalidArgument);
        }
        let parsed = super::parse_proof(proof).map_err(CliVerifyError::InvalidProof)?;
        super::verify_proof(&parsed, record, trusted_tree_size, trusted_root)
            .map_err(CliVerifyError::VerificationFailed)?;
        Ok(super::VerifiedInclusion {
            leaf_index: parsed.leaf_index,
            tree_size: trusted_tree_size,
            root: *trusted_root,
        })
    }

    /// CLI-facing outcome with an internal reason string. Not part of the
    /// stable API.
    #[derive(Debug)]
    pub enum CliVerifyError {
        InvalidProof(String),
        VerificationFailed(String),
        InvalidArgument,
    }
}

