///
/// This function performs no I/O and no printing.
pub fn verify_inclusion(
    record: &[u8],
    proof: &[u8],
    trusted_tree_size: u64,
    trusted_root: &[u8; 32],
) -> Result<VerifiedInclusion, VerifyInclusionError> {
    // Zero is rejected as a caller error before the proof is even looked at:
    // a tree of size zero contains no record, so it cannot anchor a
    // membership proof.
    if trusted_tree_size == 0 {
        return Err(VerifyInclusionError::InvalidArgument);
    }
    let parsed = parse_proof(proof).map_err(|_| VerifyInclusionError::InvalidProof)?;
    verify_proof(&parsed, record, trusted_tree_size, trusted_root)
        .map_err(|_| VerifyInclusionError::VerificationFailed)?;
    // Report the trusted values back. verify_proof has just established that
    // the proof's tree_size/root equal them and that the record binds at
    // leaf_index, so these are verified results rather than proof claims.
    Ok(VerifiedInclusion {
        leaf_index: parsed.leaf_index,
        tree_size: trusted_tree_size,
        root: *trusted_root,
    })
}

